fn id_hits(text: &str) -> Vec<(usize, usize)> {
    let p = policy();
    scan(text, p.detect_cfg())
        .into_iter()
        .filter(|h| h.det == Det::D5Id)
        .map(|h| (h.start, h.end))
        .collect()
}
fn grouped(s: &str) -> String {
    s.as_bytes()
        .chunks(4)
        .map(|c| std::str::from_utf8(c).unwrap())
        .collect::<Vec<_>>()
        .join(" ")
}

#[test]
fn i1_every_country_in_the_table_is_detected_compact_and_grouped_by_four() {
    assert_eq!(IBANS.len(), 70, "35 countries x 2");
    for (cc, iban) in IBANS {
        let text = format!("pay to {iban} today");
        let at = text.find(iban).unwrap();
        assert!(
            id_hits(&text).contains(&(at, at + iban.len())),
            "{cc}: compact {iban} not found exactly: {:?}",
            id_hits(&text)
        );
        let g = grouped(iban);
        let text = format!("pay to {g} today");
        let at = text.find(&g).unwrap();
        assert!(
            id_hits(&text).contains(&(at, at + g.len())),
            "{cc}: grouped {g} not found exactly: {:?}",
            id_hits(&text)
        );
    }
}

#[test]
fn i2_a_changed_check_digit_or_a_changed_digit_is_not_an_iban() {
    for (cc, iban) in IBANS {
        // the two check digits move by one (mod 100), the checksum no longer holds
        let cd: u32 = iban[2..4].parse().unwrap();
        let bad = format!("{}{:02}{}", &iban[..2], (cd + 1) % 100, &iban[4..]);
        assert!(
            id_hits(&format!("pay to {bad} today")).is_empty(),
            "{cc}: {bad} accepted with a wrong check digit"
        );
        // one account digit changes
        let mut b: Vec<u8> = iban.bytes().collect();
        let last = b.len() - 1;
        b[last] = if b[last] == b'9' { b'0' } else { b[last] + 1 };
        let bad = String::from_utf8(b).unwrap();
        assert!(
            id_hits(&format!("pay to {bad} today")).is_empty(),
            "{cc}: {bad} accepted with a changed digit"
        );
    }
}

#[test]
fn i3_a_country_that_is_not_in_the_table_is_not_detected_even_with_a_valid_checksum() {
    // XX is not an IBAN country; the check digits are computed for it so that mod 97 holds
    let bban = "123456789012345678";
    let n: u128 = format!("{}{}{}", bban, 33, 33).parse().unwrap(); // X = 33
    let cd = 98 - (n * 100) % 97; // append "00" for the check digits
    let iban = format!("XX{cd:02}{bban}");
    assert!(
        id_hits(&format!("pay to {iban} today")).is_empty(),
        "{iban}"
    );
}

#[test]
fn i4_text_with_non_ascii_look_alikes_is_never_an_iban_whatever_the_digits() {
    // `(?i)` matches the Kelvin sign and the long s as letters; the guard in iban_ok must refuse such text. 4,000 variants so that no accidental checksum can hide a missing guard.
    let mut x: u64 = 20261215;
    let mut next = || {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (x >> 33) as usize
    };
    for _ in 0..4000 {
        let cc = ["DE", "GB", "FR", "NL"][next() % 4];
        let len = match cc {
            "DE" | "GB" => 22,
            "FR" => 27,
            _ => 18,
        };
        let mut s: Vec<char> = format!("{cc}{:02}", next() % 100).chars().collect();
        while s.len() < len {
            s.push(char::from(b'0' + (next() % 10) as u8));
        }
        let at = 4 + next() % (len - 4);
        s[at] = ['\u{212a}', '\u{17f}'][next() % 2];
        let t: String = s.iter().collect();
        assert!(
            id_hits(&format!("pay to {t} today")).is_empty(),
            "a non-ASCII text was taken for an IBAN: {t}"
        );
    }
}
